def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    david_bid = None
    weak_count = 0
    urgent_opp = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                weak_count += 1
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                pb = prev.get('bid', 0.0)
                prev_bids.append(pb)
                if oid == 'David':
                    david_bid = pb

    if not alive:
        return float(min(budget, 18.0))

    high_pressure = max(prev_bids) if prev_bids else 0.0
    avg_pressure = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    critical = hp <= 2 or no_water >= 2
    fragile = hp <= 4 or no_water >= 1

    if critical:
        bid = 82.0 if scarcity >= 1 else 72.0
        if david_bid is not None and david_bid >= 80:
            bid = 84.0
        return float(min(budget, bid))

    if david_bid is not None and david_bid >= 80:
        if scarcity == 2:
            bid = 83.0 if fragile else 22.0
        elif scarcity == 1:
            bid = 78.0 if fragile else 16.0
        else:
            bid = 70.0 if no_water >= 1 else 12.0
    else:
        if scarcity == 2:
            bid = max(40.0, high_pressure + 2.0)
        elif scarcity == 1:
            bid = max(28.0, avg_pressure + 3.0)
        else:
            bid = max(14.0, avg_pressure + 1.5)

    if weak_count >= 2 and supply >= 19:
        bid *= 0.75
    if urgent_opp >= 2 and scarcity >= 1:
        bid *= 1.1
    if day >= 8:
        bid *= 1.15
    if hp >= 8 and no_water == 0 and scarcity == 0 and david_bid is not None and david_bid >= 80:
        bid = min(bid, 10.0)

    reserve_days = max(0, 10 - day)
    soft_cap = budget
    if reserve_days > 0:
        soft_cap = min(soft_cap, budget - max(0.0, reserve_days - 1) * 8.0)
        if soft_cap < 0:
            soft_cap = budget

    bid = min(bid, soft_cap)
    bid = max(0.0, min(budget, bid))
    return float(bid)

