        return min(my_status['budget'], max(max_prev + 5, 80.0))

    return min(my_status['budget'], max(50.0, max_prev * 0.8))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace:
            prev_bids.append(trace['bid'])
    if prev_bids:
        max_prev = max(prev_bids)
        target = max_prev + 2
        target = min(target, my_budget, DAILY_SALARY * 0.9)
        if my_hp <= 3:
            target = max(target, DAILY_SALARY * 0.8)
        return max(int(target), 1)
    else:
        base = DAILY_SALARY * 0.57
        if my_hp <= 3:
            base = DAILY_SALARY * 0.9
        base = min(base, my_budget, DAILY_SALARY * 0.85)
        return max(int(base), 1)
